-- ROLLBACK: one existing private unique helper; only duplicate raw/daily provider-name resolution is shared.
-- No source rows, original grouping, money, diagnostics, scope, grants, wrappers or prepared kernels change.
begin;
set local statement_timeout='3s';set local lock_timeout='500ms';
do $patch$
declare target regprocedure:='private.dashboard_admin_live_workorder_unique_totals(jsonb,jsonb)'::regprocedure;
 p pg_proc%rowtype;metadata jsonb;definition text;d record;protected jsonb;
 patches constant jsonb:=$patches$[{"before":"  ), daily_names as materialized (\n    select * from provider_names\n","after":"  ), daily_source as materialized (\n    select c.source,c.country_code,c.country,c.platform_key,w.platform,w.stat_date,\n      coalesce(nullif(btrim(w.third_party),''),'未识别三方') raw_provider,nullif(btrim(w.channel_type),'') channel_type,\n      w.submitted_count,w.withdraw_not_received_count,w.submitted_amount,w.withdraw_not_received_amount,\n      -- Legacy AR summaries include pending records that v46 collectors intentionally\n      -- omit from original-order details. Plain status names refer to deposits only.\n      case when c.source='ar' and jsonb_typeof(w.status_counts)='object' then\n        case when w.submitted_count is null or w.submitted_count<0 then null::bigint\n        when w.submitted_count=0 then (\n          -- WORKORDER_ZERO_DAILY_PENDING_DIAGNOSTICS_V4: zero is explicit in\n          -- this received raw row, not inferred from a missing row or another\n          -- channel. Empty state maps and valid withdrawal-only maps add no\n          -- deposit pending records. Any deposit states must all be valid zeroes.\n          select case when count(*)=0 or (\n            bool_and(s.key=any(array['待处理','处理中','已驳回','已处理','系统处理中',\n              '存款/待处理','存款/处理中','存款/已驳回','存款/已处理','存款/系统处理中',\n              '提款/待处理','提款/处理中','提款/已驳回','提款/已处理','提款/系统处理中'])\n              and coalesce(s.value ~ '^[0-9]{1,15}$',false)\n              and case when s.value ~ '^[0-9]{1,15}$'\n                then s.key like '提款/%' or s.value::bigint=0 else false end)\n            and not (bool_or(s.key like '存款/%')\n              and bool_or(s.key not like '存款/%' and s.key not like '提款/%'))\n          ) then 0::bigint end\n          from jsonb_each_text(w.status_counts) s\n        )\n        when coalesce(w.status_counts->>'存款/待处理',w.status_counts->>'待处理') ~ '^[0-9]{1,15}$'\n          then coalesce(w.status_counts->>'存款/待处理',w.status_counts->>'待处理')::bigint\n        -- WORKORDER_SPARSE_PENDING_DIAGNOSTICS_V3: collectors omit zero-count states.\n        -- Prove an omitted pending key is zero only from an entire valid deposit\n        -- state map matching this raw daily row's submitted count. Never infer it\n        -- from another channel, a withdrawal prefix, an empty map or malformed keys.\n        when not (w.status_counts ?| array['存款/待处理','待处理']) then (\n          select case when count(*)>0\n            and bool_and(s.key=any(array['处理中','已驳回','已处理','系统处理中',\n              '存款/处理中','存款/已驳回','存款/已处理','存款/系统处理中'])\n              and coalesce(s.value ~ '^[0-9]{1,15}$',false))\n            -- Mixed legacy/plain and prefixed deposit maps could double-count a\n            -- state. Keep them unknown rather than accepting a coincidental sum.\n            and not (bool_or(s.key like '存款/%') and bool_or(s.key not like '存款/%'))\n            and sum(case when s.value ~ '^[0-9]{1,15}$' then s.value::bigint end)=w.submitted_count\n            then 0::bigint end\n          from jsonb_each_text(w.status_counts) s\n          where s.key not like '提款/%'\n        ) end\n      end as deposit_pending_count\n    from (select distinct coalesce(source,'ar') source,country_code,country,platform_key from cohorts) c\n    join public.workorder_deposit_daily w on w.country_code=c.country_code and w.source_system='AR_WORKORDER'\n      and w.stat_date between v_start and v_end\n      and private.dashboard_admin_live_workorder_platform_key(w.country_code,w.platform)=c.platform_key\n    where private.dashboard_scope_allows(v_scope,w.country_code,w.platform)\n  ), daily_provider_inputs as materialized (\n    select distinct country,platform,raw_provider,channel_type from daily_source\n  ), daily_provider_routes as materialized (\n    -- Reuse exactly the current raw-input route: WG and YASH stay scalar.\n    select x.*,coalesce(x.country in ('IN','印度') and x.platform in ('YASH.BET','YASHBET'),false)\n      or exists(select 1 from scalar_platforms a where x.country in (a.country_code,a.country)\n        and x.platform=a.platform) as needs_scalar\n    from daily_provider_inputs x\n  ), daily_names as materialized (\n    select b.* from private.dashboard_admin_live_workorder_provider_batch(\n      (select coalesce(jsonb_agg(jsonb_build_object('country',country,'platform',platform,\n        'raw_provider',raw_provider,'channel_type',channel_type)),'[]'::jsonb)\n       from daily_provider_routes where not needs_scalar)) b\n    union all\n    select x.country,x.platform,x.raw_provider,x.channel_type,\n      private.dashboard_admin_live_workorder_provider(x.country,x.platform,x.raw_provider,x.channel_type)\n    from daily_provider_routes x where needs_scalar\n"},{"before":"  ), daily_source as materialized (\n    select c.source,c.country_code,c.country,c.platform_key,w.platform,w.stat_date,\n      coalesce(nullif(btrim(w.third_party),''),'未识别三方') raw_provider,nullif(btrim(w.channel_type),'') channel_type,\n      w.submitted_count,w.withdraw_not_received_count,w.submitted_amount,w.withdraw_not_received_amount,\n      -- Legacy AR summaries include pending records that v46 collectors intentionally\n      -- omit from original-order details. Plain status names refer to deposits only.\n      case when c.source='ar' and jsonb_typeof(w.status_counts)='object' then\n        case when w.submitted_count is null or w.submitted_count<0 then null::bigint\n        when w.submitted_count=0 then (\n          -- WORKORDER_ZERO_DAILY_PENDING_DIAGNOSTICS_V4: zero is explicit in\n          -- this received raw row, not inferred from a missing row or another\n          -- channel. Empty state maps and valid withdrawal-only maps add no\n          -- deposit pending records. Any deposit states must all be valid zeroes.\n          select case when count(*)=0 or (\n            bool_and(s.key=any(array['待处理','处理中','已驳回','已处理','系统处理中',\n              '存款/待处理','存款/处理中','存款/已驳回','存款/已处理','存款/系统处理中',\n              '提款/待处理','提款/处理中','提款/已驳回','提款/已处理','提款/系统处理中'])\n              and coalesce(s.value ~ '^[0-9]{1,15}$',false)\n              and case when s.value ~ '^[0-9]{1,15}$'\n                then s.key like '提款/%' or s.value::bigint=0 else false end)\n            and not (bool_or(s.key like '存款/%')\n              and bool_or(s.key not like '存款/%' and s.key not like '提款/%'))\n          ) then 0::bigint end\n          from jsonb_each_text(w.status_counts) s\n        )\n        when coalesce(w.status_counts->>'存款/待处理',w.status_counts->>'待处理') ~ '^[0-9]{1,15}$'\n          then coalesce(w.status_counts->>'存款/待处理',w.status_counts->>'待处理')::bigint\n        -- WORKORDER_SPARSE_PENDING_DIAGNOSTICS_V3: collectors omit zero-count states.\n        -- Prove an omitted pending key is zero only from an entire valid deposit\n        -- state map matching this raw daily row's submitted count. Never infer it\n        -- from another channel, a withdrawal prefix, an empty map or malformed keys.\n        when not (w.status_counts ?| array['存款/待处理','待处理']) then (\n          select case when count(*)>0\n            and bool_and(s.key=any(array['处理中','已驳回','已处理','系统处理中',\n              '存款/处理中','存款/已驳回','存款/已处理','存款/系统处理中'])\n              and coalesce(s.value ~ '^[0-9]{1,15}$',false))\n            -- Mixed legacy/plain and prefixed deposit maps could double-count a\n            -- state. Keep them unknown rather than accepting a coincidental sum.\n            and not (bool_or(s.key like '存款/%') and bool_or(s.key not like '存款/%'))\n            and sum(case when s.value ~ '^[0-9]{1,15}$' then s.value::bigint end)=w.submitted_count\n            then 0::bigint end\n          from jsonb_each_text(w.status_counts) s\n          where s.key not like '提款/%'\n        ) end\n      end as deposit_pending_count\n    from (select distinct coalesce(source,'ar') source,country_code,country,platform_key from cohorts) c\n    join public.workorder_deposit_daily w on w.country_code=c.country_code and w.source_system='AR_WORKORDER'\n      and w.stat_date between v_start and v_end\n      and private.dashboard_admin_live_workorder_platform_key(w.country_code,w.platform)=c.platform_key\n    where private.dashboard_scope_allows(v_scope,w.country_code,w.platform)\n  ), provider_inputs as materialized (\n    -- One exact native tuple map for both record and daily evidence in this request.\n    select country,platform,raw_provider,channel_type from raw_details\n    union\n    select country,platform,raw_provider,channel_type from daily_source\n","after":"  ), provider_inputs as materialized (\n    select distinct country,platform,raw_provider,channel_type from raw_details\n"}]$patches$::jsonb;
begin
 if current_user<>'postgres'then raise exception 'workorder_shared_names_owner_required';end if;
 select *into p from pg_proc where oid=target;
 if p.proowner<>'postgres'::regrole or p.proacl::text is distinct from '{postgres=X/postgres}'
 or p.prosecdef or p.provolatile<>'s'or p.proconfig is distinct from array['search_path=""']
 or p.proparallel<>'u'or p.proisstrict or p.proleakproof or p.pronargdefaults<>0
 or pg_get_function_arguments(target)<>'p_request jsonb, p_result jsonb'or pg_get_function_result(target)<>'jsonb'
 then raise exception 'workorder_shared_names_metadata_drift';end if;
 for d in select *from(values
 ('private.dashboard_admin_live_workorder_provider(text,text,text,text)','3eeda654b2724af8537776ed812458fe'),
 ('private.dashboard_admin_live_workorder_provider_batch(jsonb)','12cc504d23658ed10d677deebb7e7049'),
 ('private.dashboard_admin_live_provider_canonical(text,text,text)','008e5cee3a4f6ac9e90706c45bee56da'),
 ('private.dashboard_admin_wg_provider_aliases()','5dedf6cf8a430e21b69ca81069db8b3b')
 )x(signature,body_md5)loop
  if not exists(select 1 from pg_proc dp where dp.oid=to_regprocedure(d.signature)and md5(dp.prosrc)=d.body_md5)
  then raise exception 'workorder_shared_names_mapping_dependency_drift';end if;
 end loop;
 for d in select *from(values
 ('private.prepared_aggregate_dependency_common(text)','36966b6e1e434eb6d5990e551f816b8e','1c8080bcc9742302e3cf5c11ef565c40'),
 ('private.provider_snapshot_dependency_token(jsonb)','ccf807a978ba7f0d3cb9f527dad6c5d4','94146d61170c7a3cc87db9e04be01854')
 )x(signature,body_md5,definition_md5)loop
  if not exists(select 1 from pg_proc dp where dp.oid=to_regprocedure(d.signature)and md5(dp.prosrc)=d.body_md5 and md5(pg_get_functiondef(dp.oid))=d.definition_md5)
  then raise exception 'workorder_shared_names_financial_dependency_drift';end if;
 end loop;
 select jsonb_agg(to_jsonb(dp)order by dp.oid)into protected from pg_proc dp where dp.oid in(
 'private.prepared_aggregate_dependency_common(text)'::regprocedure,'private.provider_snapshot_dependency_token(jsonb)'::regprocedure);
 if md5(p.prosrc)='39393d9ff3333631da2086cb42517fd9'and md5(pg_get_functiondef(target))='f15d863db5a96c0045cb7ee3f382cac4'then return;end if;
 if md5(p.prosrc)<>'7a0c9a592bca8642dcd60e685f5ee49c'or md5(pg_get_functiondef(target))<>'ce7c3d92f1392c9ea879026f014c3dfe'
 then raise exception 'workorder_shared_names_baseline_drift';end if;
 metadata:=to_jsonb(p)-'prosrc';definition:=pg_get_functiondef(target);
 for d in select value->>'before' before_text,value->>'after' after_text from jsonb_array_elements(patches)loop
  if position(d.before_text in definition)=0 or position(d.before_text in substring(definition from position(d.before_text in definition)+length(d.before_text)))>0
  then raise exception 'workorder_shared_names_replacement_not_unique';end if;
  definition:=replace(definition,d.before_text,d.after_text);
 end loop;
 execute definition;
 select *into p from pg_proc where oid=target;
 if md5(p.prosrc)<>'39393d9ff3333631da2086cb42517fd9'or md5(pg_get_functiondef(target))<>'f15d863db5a96c0045cb7ee3f382cac4'or(to_jsonb(p)-'prosrc')is distinct from metadata
 then raise exception 'workorder_shared_names_postcondition_failed';end if;
 if protected is distinct from(select jsonb_agg(to_jsonb(dp)order by dp.oid)from pg_proc dp where dp.oid in(
 'private.prepared_aggregate_dependency_common(text)'::regprocedure,'private.provider_snapshot_dependency_token(jsonb)'::regprocedure))
 then raise exception 'workorder_shared_names_financial_dependency_changed';end if;
end;$patch$;
commit;
